}

log(`Branch: ${ctx.branch}, SPEC: ${specContent.split('\n').length} lines`)

const priorFailures: string = [
  ctx.prior_defects || '',
  ctx.error_history || '',
].filter(Boolean).join('\n') || '(no prior failure data)'

