export const meta = {
  name: 'datum-go',
  description: 'Full pipeline: TICKET → SPEC → Plan → Properties → Act → Validate → Review → Closeout',
  phases: [
    { title: 'Refine', detail: 'TICKET.md → SPEC.md' },
    { title: 'Plan', detail: 'SPEC.md → tasks.json + lane-plan.json' },
    { title: 'Properties', detail: '11-category invariants' },
    { title: 'Act', detail: 'TDD pipeline: RED → GREEN → REFACTOR per lane' },
    { title: 'Validate', detail: 'full test suite + lint + AC check' },
    { title: 'Review', detail: '4-domain parallel review swarm' },
    { title: 'Closeout', detail: 'collect → synthesize → archive' },
  ],
}

// ── Parse args ──

const rawArgs: string = typeof args === 'string' ? args.trim().replace(/^"|"$/g, '').trim() : ''
const a = (typeof args === 'string')
  ? (rawArgs.toLowerCase() === 'yolo' ? { yolo: true } : JSON.parse(args))
  : (args || {})

const yolo: boolean = !!a.yolo
const startFrom: string = (a.startFrom || 'refine').toLowerCase()
const wfArgs = yolo ? '"yolo"' : undefined

const PHASE_ORDER = ['refine', 'plan', 'properties', 'act', 'validate', 'review', 'closeout']
const startIdx = PHASE_ORDER.indexOf(startFrom)
if (startIdx === -1) {
  throw new Error(`Unknown phase: ${startFrom}. Valid: ${PHASE_ORDER.join(', ')}`)
}

log(`datum go — starting from ${startFrom}${yolo ? ' (yolo mode)' : ''}`)

// ── Pipeline ──

interface PhaseResult {
  gatePassed?: boolean
  gateMessage?: string
  [key: string]: unknown
}

let lastResult: PhaseResult = {}

// Refine
if (startIdx <= 0) {
  phase('Refine')
  lastResult = await workflow(
    { scriptPath: 'skills/datum-refine.js' },
    yolo ? 'yolo' : {},
  ) as PhaseResult

  if (!yolo && !lastResult.gatePassed) {
    log(`Refine gate held: ${lastResult.gateMessage || 'needs review'}`)
    log('Run with yolo or address gaps in QUESTIONS.md, then: datum go --start-from plan')
    export const __workflowResult = { phase: 'refine', halted: true, ...lastResult }
  }
  log('Refine complete')
}

// Plan
if (startIdx <= 1) {
  phase('Plan')
  lastResult = await workflow(
    { scriptPath: 'skills/datum-plan.js' },
    yolo ? 'yolo' : {},
  ) as PhaseResult

  if (!lastResult.gatePassed) {
    log(`Plan gate held: ${lastResult.gateMessage || 'needs human approval (--approve)'}`)
    log('Review TASKS.md + lane-plan.json, then: datum go --start-from properties')
    export const __workflowResult = { phase: 'plan', halted: true, ...lastResult }
  }
  log(`Plan complete — ${(lastResult as { taskCount?: number }).taskCount || '?'} tasks`)
}

// Properties
if (startIdx <= 2) {
  phase('Properties')
  lastResult = await workflow(
    { scriptPath: 'skills/datum-properties.js' },
    yolo ? 'yolo' : {},
  ) as PhaseResult
  log('Properties complete')
}

// Act
if (startIdx <= 3) {
  phase('Act')
  lastResult = await workflow(
    { scriptPath: 'skills/datum-tdd-act.js' },
    yolo ? 'yolo' : {},
  ) as PhaseResult

  const actResult = lastResult as { completed?: number; failed?: number; failedLanes?: string[] }
  log(`Act complete — ${actResult.completed || 0} succeeded, ${actResult.failed || 0} failed`)

  if ((actResult.failed || 0) > 0) {
    log(`Failed lanes: ${(actResult.failedLanes || []).join(', ')}`)
  }
}

// Validate
if (startIdx <= 4) {
  phase('Validate')
  lastResult = await workflow(
    { scriptPath: 'skills/datum-validate.js' },
    yolo ? 'yolo' : {},
  ) as PhaseResult

  if (!(lastResult as { testsPassed?: boolean }).testsPassed) {
    log('Validate FAILED — tests are red. Pipeline halted.')
    export const __workflowResult = { phase: 'validate', halted: true, ...lastResult }
  }
  log('Validate complete')
}

// Review
if (startIdx <= 5) {
  phase('Review')
  lastResult = await workflow(
    { scriptPath: 'skills/datum-review.js' },
    yolo ? 'yolo' : {},
  ) as PhaseResult

  const reviewResult = lastResult as { criticalFindings?: number; canMerge?: boolean }
  if (!reviewResult.canMerge) {
    log(`Review found ${reviewResult.criticalFindings || '?'} critical issues — remediation needed`)
    log('Fix issues, then: datum go --start-from validate')
    export const __workflowResult = { phase: 'review', halted: true, ...lastResult }
  }
  log('Review complete — clear to merge')
}

// Closeout
if (startIdx <= 6) {
  phase('Closeout')
  lastResult = await workflow(
    { scriptPath: 'skills/datum-closeout.js' },
    yolo ? 'yolo' : {},
  ) as PhaseResult
  log('Closeout complete')
}

log('\n' + '='.repeat(60))
log('DATUM GO COMPLETE — full pipeline finished')
log('='.repeat(60))

export const __workflowResult = {
  phase: 'complete',
  halted: false,
  ...lastResult,
}

