import type { LanePlan, LaneOutcome, SetupResult, LaneResult } from './shared/types'
import { buildWaves, parseAgentJson } from './shared/utils'

export const meta = {
  name: 'datum-tdd-act',
  description: 'Deterministic TDD Act: RED->GREEN->REFACTOR per lane with gate enforcement',
  phases: [
    { title: 'Topology', detail: 'parse lane-plan.json, BFS wave grouping, auto-partition into ≤5 task batches' },
    { title: 'Setup', detail: 'create root + per-lane git worktrees (per batch)' },
    { title: 'Act', detail: 'RED->verify->GREEN->verify->REFACTOR per lane, DAG-parallel (per batch)' },
    { title: 'Merge', detail: 'squash-merge lanes in topological order (per batch)' },
    { title: 'Cleanup', detail: 'remove worktrees (per batch)' },
    { title: 'Docs', detail: 'haiku pre-check + conditional sonnet sync (once after all batches)' },
    { title: 'Triage', detail: 'analyze failures, auto-file issues on the board' },
  ],
}

// ── Parse args ──
// "yolo" mode: auto-detect epicBranch from current git branch, generate runId from timestamp

const rawArgs: string = typeof args === 'string' ? args.trim().replace(/^"|"$/g, '').trim() : ''
const a = (typeof args === 'string')
  ? (rawArgs.toLowerCase() === 'yolo' ? { yolo: true } : JSON.parse(args))
  : (args || {})

const lanePlanPath: string = a.lanePlanPath || '.datum/lane-plan.json'
const testCommand: string = a.testCommand || 'uv run pytest -x -q'
const language: string = a.language || 'python'

let epicBranch: string = a.epicBranch
let runId: string = a.runId

// yolo mode: auto-detect branch and generate runId via agent
const branchInfo = a.yolo
  ? await agent(
      `Run these two commands and return ONLY a JSON object with two fields:
1. "branch": output of \`git rev-parse --abbrev-ref HEAD\`
2. "timestamp": output of \`date +%Y%m%d-%H%M%S\`
Output raw JSON only. No markdown fences, no explanation.`,
      { label: 'yolo-detect', model: 'haiku' },
    )
  : null

if (branchInfo) {
  const info = typeof branchInfo === 'string'
    ? JSON.parse(branchInfo.replace(/```[a-z]*\n?/g, '').trim())
    : branchInfo
  epicBranch = epicBranch || info.branch
  runId = runId || info.timestamp
}

if (!epicBranch) throw new Error('args.epicBranch is required. Pass {epicBranch, runId} or "yolo" to auto-detect.')
if (!runId) throw new Error('args.runId is required. Pass {epicBranch, runId} or "yolo" to auto-detect.')

// ── Topology ──

phase('Topology')

const planText = await agent(
  `Read ${lanePlanPath} and return its contents as raw JSON text. This is the SOLE source of truth — do NOT read tasks.json or any other file. Output ONLY the JSON, no markdown fences, no explanation.`,
  { label: 'read-plan', phase: 'Topology', model: 'haiku' }
)
const lanePlan: LanePlan = typeof planText === 'string'
  ? JSON.parse(planText.replace(/```[a-z]*\n?/g, '').trim())
  : planText

const waves = buildWaves(lanePlan)
if (waves.length === 0 || Object.keys(lanePlan.lanes || {}).length === 0) {
  throw new Error('Lane plan has 0 tasks — nothing to execute')
}
log(`Topology: ${lanePlan.total_lanes} lanes in ${waves.length} waves`)
for (let i = 0; i < waves.length; i++) {
  log(`  Wave ${i}: [${waves[i].join(', ')}]`)
}

// ── Batch partitioning ──

const MAX_BATCH = 5
const allLaneIds = lanePlan.topological_order
const batches: string[][] = []
for (let i = 0; i < allLaneIds.length; i += MAX_BATCH) {
  batches.push(allLaneIds.slice(i, i + MAX_BATCH))
}

if (batches.length > 1) {
  log(`Auto-partitioned ${lanePlan.total_lanes} tasks into ${batches.length} batches (max ${MAX_BATCH}/batch)`)
  for (let b = 0; b < batches.length; b++) {
    log(`  Batch ${b}: [${batches[b].join(', ')}]`)
  }
}

// ── Batch loop ──

const results: Record<string, LaneOutcome> = {}
const failures: string[] = []
const completedLanes: string[] = []

for (let bi = 0; bi < batches.length; bi++) {
  const batchLaneIds = batches[bi]
  const batchTag = batches.length > 1 ? ` [batch ${bi + 1}/${batches.length}]` : ''
  const batchRunId = batches.length > 1 ? `${runId}-b${bi}` : runId

  if (batches.length > 1) log(`\n${'='.repeat(60)}\n=== Batch ${bi + 1}/${batches.length}: [${batchLaneIds.join(', ')}] ===\n${'='.repeat(60)}`)

  // Setup
  phase('Setup')
  const setup = await workflow(
    { scriptPath: 'skills/datum-tdd-act-setup.js' },
    { batchRunId, epicBranch, batchLaneIds, lanePlan, batchTag }
  ) as SetupResult

  // Act
  phase('Act')
  const act = await workflow(
    { scriptPath: 'skills/datum-tdd-act-lane.js' },
    {
      batchLaneIds, lanePlan, worktreePaths: setup.worktreePaths, batchTag,
      cfg: { lanePlanPath, epicBranch, runId: batchRunId, testCommand, language },
      priorFailures: failures,
    }
  ) as LaneResult

  // Collect results
  for (const [id, r] of Object.entries(act.results || {})) {
    results[id] = r
    if (!r || r.status !== 'completed') {
      failures.push(id)
      log(`  FAILED ${id}: ${r ? `${r.stage} — ${r.error}` : 'null result'}`)
    } else {
      completedLanes.push(id)
    }
  }
  log(`Act${batchTag} done: ${batchLaneIds.filter(id => completedLanes.includes(id)).length}/${batchLaneIds.length} succeeded`)

  // Merge + Cleanup
  phase('Merge')
  await workflow(
    { scriptPath: 'skills/datum-tdd-act-merge.js' },
    {
      epicBranch,
      completedIds: batchLaneIds.filter(id => completedLanes.includes(id)),
      batchRunId,
      topoOrder: lanePlan.topological_order,
      batchTag,
    }
  )
}

// ── Docs ──

phase('Docs')
await workflow(
  { scriptPath: 'skills/datum-tdd-act-docs.js' },
  { completedLanes, lanePlan, runId }
)

// ── Summary ──

log(`\n${'═'.repeat(60)}`)
log(`ACT COMPLETE: ${completedLanes.length}/${lanePlan.total_lanes} succeeded, ${failures.length} failed`)
if (completedLanes.length > 0) log(`  completed: [${completedLanes.join(', ')}]`)
if (failures.length > 0) {
  log(`  failed:    [${failures.join(', ')}]`)
  for (const fid of failures) {
    const r = results[fid]
    if (r) log(`    ${fid}: ${r.stage} — ${r.error}`)
  }
}
log(`${'═'.repeat(60)}`)

// ── Triage ──

if (failures.length > 0) {
  phase('Triage')
  await workflow(
    { scriptPath: 'skills/datum-tdd-act-triage.js' },
    { failures, results, lanePlan, runId, epicBranch }
  )
}

export const __workflowResult = {
  runId,
  total: lanePlan.total_lanes,
  completed: completedLanes.length,
  failed: failures.length,
  failedLanes: failures,
  completedLanes,
}

import type { SetupArgs } from './shared/types'
import { parseAgentJson } from './shared/utils'

export const meta = {
  name: 'datum-tdd-act-setup',
  description: 'Create root + per-lane git worktrees and distribute lane plan',
  phases: [{ title: 'Setup' }],
}

const a = args as SetupArgs
phase('Setup')

const rootWtText = await agent(
  `git worktree add --detach .datum/worktrees/${a.batchRunId}-root ${a.epicBranch} 2>&1 && ` +
  `echo '{"root": "'$(cd .datum/worktrees/${a.batchRunId}-root && pwd)'"}'`,
  { label: `root-wt${a.batchTag}`, phase: 'Setup', model: 'haiku' }
)
const rootWtInfo = parseAgentJson(rootWtText, {}) as { root?: string }
const rootWt = rootWtInfo.root
if (!rootWt) throw new Error(`Failed to create root worktree for ${a.batchRunId}`)
log(`Root worktree${a.batchTag}: ${rootWt}`)

const setupText = await agent(
  `cd "${rootWt}" && datum worktrees setup --run-id ${a.batchRunId} --epic-branch ${a.epicBranch} --lane-ids ${a.batchLaneIds.join(',')}\nReturn ONLY the JSON output, no explanation.`,
  { label: `setup-wt${a.batchTag}`, phase: 'Setup', model: 'haiku' }
)
const worktreePaths: Record<string, string> = typeof setupText === 'string'
  ? JSON.parse(setupText.replace(/```[a-z]*\n?/g, '').trim())
  : setupText

const validPaths = Object.values(worktreePaths || {}).filter(Boolean)
if (validPaths.length === 0) throw new Error(`Setup failed: no worktree paths for ${a.batchRunId}`)
for (const [lid, wtp] of Object.entries(worktreePaths || {})) {
  log(`  worktree ${lid}: ${wtp}`)
}

const planJson = JSON.stringify(a.lanePlan).replace(/'/g, "'\\''")
await agent(
  `mkdir -p "${rootWt}/.datum" && printf '%s' '${planJson}' > "${rootWt}/.datum/lane-plan.json"`,
  { label: `write-plan${a.batchTag}`, phase: 'Setup', model: 'haiku' }
)
const cpCmd = validPaths
  .map(p => `mkdir -p "${p}/.datum" && cp "${rootWt}/.datum/lane-plan.json" "${p}/.datum/lane-plan.json"`)
  .join(' && ')
if (cpCmd) {
  await agent(cpCmd, { label: `copy-plans${a.batchTag}`, phase: 'Setup', model: 'haiku' })
}

log(`Setup${a.batchTag}: ${a.batchLaneIds.length} lane worktrees`)

export const __workflowResult = { worktreePaths }

import type { MergeArgs } from './shared/types'

export const meta = {
  name: 'datum-tdd-act-merge',
  description: 'Squash-merge completed lanes in topological order, then cleanup worktrees',
  phases: [{ title: 'Merge' }, { title: 'Cleanup' }],
}

const a = args as MergeArgs

// ── Merge ──
phase('Merge')

if (a.completedIds.length === 0) {
  log(`No lanes completed${a.batchTag} — skipping merge`)
} else {
  const mergeOrder = a.topoOrder.filter(id => a.completedIds.includes(id))
  await agent(
    `datum worktrees merge --epic-branch ${a.epicBranch} --lane-order ${mergeOrder.join(',')} ` +
    `--commit-message "act(${a.batchRunId}): merge ${a.completedIds.length} lanes"`,
    { label: `merge${a.batchTag}`, phase: 'Merge', model: 'haiku' }
  )
  log(`Merged${a.batchTag} in order: [${mergeOrder.join(' → ')}]`)
}

// ── Cleanup ──
phase('Cleanup')

await agent(
  `datum worktrees cleanup --run-id ${a.batchRunId} --epic-branch ${a.epicBranch} && ` +
  `git worktree remove .datum/worktrees/${a.batchRunId}-root --force 2>/dev/null; ` +
  `git worktree prune`,
  { label: `cleanup${a.batchTag}`, phase: 'Cleanup', model: 'haiku' }
)

export const __workflowResult = { merged: a.completedIds.length > 0 }

import type { DocsArgs, WriteResult } from './shared/types'
import { WRITE_RESULT_SCHEMA, COMMIT_RESULT_SCHEMA, REFACTOR_CHECK_SCHEMA } from './shared/schemas'
import { commitStage } from './shared/agents'
import { docsCheckPrompt, docsSyncPrompt } from './shared/prompts'

export const meta = {
  name: 'datum-tdd-act-docs',
  description: 'Haiku pre-check + conditional sonnet docs sync with git commit',
  phases: [{ title: 'Docs' }],
}

const a = args as DocsArgs
phase('Docs')

let synced = false
let syncedFiles: string[] | undefined

if (a.completedLanes.length === 0) {
  log('No completed lanes — skipping docs')
} else {
  const changedFiles = [...new Set(a.completedLanes.flatMap(id => a.lanePlan.lanes[id].files || []))]

  const docsCheck = await agent(
    docsCheckPrompt({ changedFiles: changedFiles.join(', ') }),
    { label: 'docs-check', phase: 'Docs', model: 'haiku', schema: REFACTOR_CHECK_SCHEMA }
  )

  if (docsCheck?.should_refactor) {
    const docsPacket = JSON.stringify({
      schema_version: '1.0',
      changed_files: changedFiles,
      new_symbols: a.completedLanes.map(id => ({
        task_id: id,
        title: a.lanePlan.lanes[id].title,
        files: a.lanePlan.lanes[id].files,
      })),
      working_directory: '.',
    })

    const docs = await agent(
      docsSyncPrompt({ docsPacket }),
      { label: 'docs-sync', phase: 'Docs', model: 'sonnet', schema: WRITE_RESULT_SCHEMA }
    ) as WriteResult | null

    if (docs?.success) {
      const docsWritten = docs.files_written || []
      if (docsWritten.length === 0) {
        log('Docs: agent reported success but no files_written — skipping commit')
      } else {
        await commitStage('docs', '.', `docs(${a.runId})`, docsWritten, 'DOCS')
      }
      log(`Docs synced: ${docsWritten.join(', ')}`)
      synced = true
      syncedFiles = docsWritten
    } else {
      log(`Docs: ${docs?.failure_reason || 'nothing to update'}`)
    }
  } else {
    log('Docs: no stale references found, skipping')
  }
}

export const __workflowResult = { synced, files: syncedFiles }

import type { TriageArgs, TriageAnalysis } from './shared/types'
import { TRIAGE_SCHEMA } from './shared/schemas'

export const meta = {
  name: 'datum-tdd-act-triage',
  description: 'Categorize TDD failures and auto-file GitHub issues',
  phases: [{ title: 'Triage' }],
}

const a = args as TriageArgs
phase('Triage')

let filed = 0

if (a.failures.length === 0) {
  log('[triage] All lanes succeeded — no issues to file')
} else {
  const failureDetails = a.failures.map(fid => {
    const r = a.results[fid]
    const lane = a.lanePlan.lanes[fid]
    return `Lane ${fid} ("${lane?.title || 'unknown'}"): failed at ${r?.stage || 'UNKNOWN'} — ${r?.error || 'null result'}`
  }).join('\n')

  const triage = await agent(
    `Analyze these TDD workflow failures and categorize each one.\n\n` +
    `Run ID: ${a.runId}\n` +
    `Epic branch: ${a.epicBranch}\n` +
    `Failed lanes:\n${failureDetails}\n\n` +
    `For each failure, determine:\n` +
    `- Is this a WORKFLOW BUG (datum-tdd-act.js logic error)?\n` +
    `- Is this a LANE PLAN issue (bad ACs, wrong files, missing deps)?\n` +
    `- Is this an AGENT BEHAVIOR issue (agent didn't follow instructions)?\n` +
    `- Is this INFRASTRUCTURE (git, uv, pytest, CWD issues)?\n` +
    `- Is this TEST QUALITY (tests too weak, wrong assertions)?\n\n` +
    `For each issue, write a GitHub issue title starting with [datum-bug] and a body with:\n` +
    `- What happened (the error)\n` +
    `- Why it happened (root cause analysis)\n` +
    `- Suggested fix\n` +
    `- The lane, stage, and run ID for traceability`,
    { label: 'triage', phase: 'Triage', model: 'sonnet', schema: TRIAGE_SCHEMA }
  ) as TriageAnalysis | null

  if (triage?.issues?.length) {
    for (const issue of triage.issues) {
      if (issue.severity === 'low') {
        log(`[triage] Skipping low-severity: ${issue.title}`)
        continue
      }
      const labels = `datum-bug,${issue.category}`
      const safeTitle = issue.title.slice(0, 80).replace(/'/g, "'\\''")
      const safeSearch = issue.title.slice(0, 50).replace(/'/g, "'\\''")
      const safeBody = issue.body.replace(/'/g, "'\\''")
      await agent(
        `unset GITHUB_TOKEN && gh issue list --repo gitrdunhq/datum --state open --search '${safeSearch}' --json number,title --limit 3 | head -5\n` +
        `If no duplicate exists, create the issue:\n` +
        `unset GITHUB_TOKEN && gh issue create --repo gitrdunhq/datum ` +
        `--title '${safeTitle}' ` +
        `--label '${labels}' ` +
        `--body '${safeBody}'\n` +
        `If a duplicate exists, skip and say "duplicate found".`,
        { label: `file-issue:${issue.lane || 'global'}`, phase: 'Triage', model: 'haiku' }
      )
      log(`[triage] Filed: ${issue.title} [${issue.category}/${issue.severity}]`)
      filed++
    }
  } else {
    log('[triage] No actionable issues identified')
  }
}

export const __workflowResult = { filed }

