export const meta = {
  name: 'datum-go',
  description: 'Full pipeline: TICKET → SPEC → Plan → Properties → Act → Validate → Review → Closeout',
  phases: [],
}

// ── Parse args ──

const rawArgs: string = typeof args === 'string' ? args.trim().replace(/^"|"$/g, '').trim() : ''
const a = (typeof args === 'string')
  ? (rawArgs.toLowerCase() === 'yolo' ? { yolo: true } : JSON.parse(args))
  : (args || {})

const yolo: boolean = !!a.yolo
const startFrom: string = (a.startFrom || 'refine').toLowerCase()

const PHASE_ORDER = ['refine', 'plan', 'properties', 'act', 'validate', 'review', 'closeout']
const startIdx = PHASE_ORDER.indexOf(startFrom)
if (startIdx === -1) {
  throw new Error(`Unknown phase: ${startFrom}. Valid: ${PHASE_ORDER.join(', ')}`)
}

log(`datum go — starting from ${startFrom}${yolo ? ' (yolo mode)' : ''}`)

// ── Pipeline ──

interface PhaseResult {
  gatePassed?: boolean
  gateMessage?: string
  testsPassed?: boolean
  criticalFindings?: number
  canMerge?: boolean
  completed?: number
  failed?: number
  failedLanes?: string[]
  taskCount?: number
  [key: string]: unknown
}

let lastResult: PhaseResult = {}
let haltedAt = ''

// Refine
if (!haltedAt && startIdx <= 0) {
  log('── Refine ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-refine.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.gatePassed) {
    haltedAt = 'refine'
    log(`Refine gate held: ${lastResult.gateMessage || 'needs review'}. Address QUESTIONS.md, then: datum go --start-from plan`)
  } else {
    log('Refine complete')
  }
}

// Plan
if (!haltedAt && startIdx <= 1) {
  log('── Plan ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-plan.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.gatePassed) {
    haltedAt = 'plan'
    log(`Plan gate held: ${lastResult.gateMessage || 'needs approval'}. Review TASKS.md, then: datum go --start-from properties`)
  } else {
    log(`Plan complete — ${lastResult.taskCount || '?'} tasks`)
  }
}

// Properties
if (!haltedAt && startIdx <= 2) {
  log('── Properties ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-properties.js' }, yolo ? 'yolo' : {}) as PhaseResult
  log('Properties complete')
}

// Act
if (!haltedAt && startIdx <= 3) {
  log('── Act ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-tdd-act.js' }, yolo ? 'yolo' : {}) as PhaseResult
  log(`Act complete — ${lastResult.completed || 0} succeeded, ${lastResult.failed || 0} failed`)
  if ((lastResult.failed || 0) > 0) {
    log(`Failed lanes: ${(lastResult.failedLanes || []).join(', ')}`)
  }
}

// Validate
if (!haltedAt && startIdx <= 4) {
  log('── Validate ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-validate.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.testsPassed) {
    haltedAt = 'validate'
    log('Validate FAILED — tests are red. Pipeline halted.')
  } else {
    log('Validate complete')
  }
}

// Review
if (!haltedAt && startIdx <= 5) {
  log('── Review ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-review.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.canMerge) {
    haltedAt = 'review'
    log(`Review: ${lastResult.criticalFindings || '?'} critical issues. Fix, then: datum go --start-from validate`)
  } else {
    log('Review complete — clear to merge')
  }
}

// Closeout
if (!haltedAt && startIdx <= 6) {
  log('── Closeout ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-closeout.js' }, yolo ? 'yolo' : {}) as PhaseResult
  log('Closeout complete')
}

if (haltedAt) {
  log(`\nPipeline halted at ${haltedAt}. Resume with: datum go --start-from <next-phase>`)
} else {
  log('\n' + '='.repeat(60))
  log('DATUM GO COMPLETE')
  log('='.repeat(60))
}

export const __workflowResult = {
  phase: haltedAt || 'complete',
  halted: !!haltedAt,
  ...lastResult,
}

// Pure utility functions for the datum TDD workflow pipeline.
// Every function here is deterministic and side-effect-free.

import type {
  LanePlan,
  Lane,
  PipelineConfig,
  TaskPacket,
  SkepticResult,
  SkepticLens,
} from './types'

// ---------------------------------------------------------------------------
// Local types
// ---------------------------------------------------------------------------

export interface ContractEntry {
  function: string
  args: string[]
  returns: string | null
  raises: string | null
  ac: string
}

// ---------------------------------------------------------------------------
// buildWaves — Kahn's algorithm BFS wave grouping
// ---------------------------------------------------------------------------

export function buildWaves(lanePlan: LanePlan): string[][] {
  const lanes = lanePlan.lanes
  const ids = Object.keys(lanes)
  const inDeg: Record<string, number> = {}
  const adj: Record<string, string[]> = {}

  for (const id of ids) {
    const deps = lanes[id].depends_on || []
    for (const dep of deps) {
      if (!lanes[dep]) {
        throw new Error(
          `Task '${id}' depends on '${dep}', which does not exist in the lane plan`,
        )
      }
    }
    inDeg[id] = deps.length
    for (const dep of deps) {
      ;(adj[dep] = adj[dep] || []).push(id)
    }
  }

  const waves: string[][] = []
  let queue = ids.filter((id) => inDeg[id] === 0).sort()

  while (queue.length > 0) {
    waves.push([...queue])
    const next: string[] = []
    for (const id of queue) {
      for (const child of adj[id] || []) {
        inDeg[child]--
        if (inDeg[child] === 0) next.push(child)
      }
    }
    queue = next.sort()
  }

  const placed = new Set(waves.flat())
  const cyclic = ids.filter((id) => !placed.has(id))
  if (cyclic.length > 0) {
    throw new Error(
      `Cyclic dependency detected among tasks: ${cyclic.sort().join(', ')}`,
    )
  }

  return waves
}

// ---------------------------------------------------------------------------
// classifyFiles — separates test files from implementation files
// ---------------------------------------------------------------------------

export function classifyFiles(files: string[]): {
  testFiles: string[]
  implFiles: string[]
} {
  const isTest = (f: string): boolean => {
    const base = f.split('/').pop() || ''
    return (
      base.startsWith('test_') ||
      base.endsWith('_test.py') ||
      base.endsWith('.test.ts') ||
      base.endsWith('.test.js') ||
      base.endsWith('.spec.ts') ||
      base.endsWith('.spec.js') ||
      base.endsWith('_test.go') ||
      base.endsWith('Tests.swift') ||
      f.includes('/tests/') ||
      f.includes('/Tests/') ||
      base === 'conftest.py'
    )
  }
  const testFiles = (files || []).filter(isTest)
  const implFiles = (files || []).filter((f) => !isTest(f))
  return { testFiles, implFiles }
}

// ---------------------------------------------------------------------------
// parseAgentJson — extracts JSON from agent text output
// ---------------------------------------------------------------------------

export function parseAgentJson<T = unknown>(text: string, fallback: T): T {
  if (!text || typeof text !== 'string') return fallback
  const cleaned = text.replace(/```[a-z]*\n?/g, '').trim()
  const start = cleaned.search(/[{[]/)
  const end = Math.max(cleaned.lastIndexOf('}'), cleaned.lastIndexOf(']'))
  if (start === -1 || end === -1) return fallback
  try {
    return JSON.parse(cleaned.slice(start, end + 1)) as T
  } catch {
    return fallback
  }
}

// ---------------------------------------------------------------------------
// laneCtxCmd — builds a shell command that writes lane-context.json
// ---------------------------------------------------------------------------

export function laneCtxCmd(packet: TaskPacket, wt: string): string {
  const ctx = JSON.stringify({
    task_id: packet.task_id,
    stage: packet.stage,
    allowed_write_files: packet.allowed_write_files,
    forbidden_write_files: packet.forbidden_write_files,
    commit_prefix: packet.commit_prefix,
    test_count_floor: 0,
  })
  return `mkdir -p "${wt}/.datum" && printf '%s' '${ctx.replace(/'/g, "'\\''")}' > "${wt}/.datum/lane-context.json"`
}

// ---------------------------------------------------------------------------
// extractContractSummary — extracts function signatures from AC text
// ---------------------------------------------------------------------------

const BUILTIN_SKIP = new Set([
  'print',
  'len',
  'str',
  'int',
  'dict',
  'list',
  'set',
  'isinstance',
  'type',
  'exit',
  'round',
  'sorted',
  'filter',
  'map',
  'any',
  'all',
  'range',
  'enumerate',
  'zip',
  'open',
  'input',
  'format',
  'repr',
  'hash',
  'id',
  'dir',
  'vars',
  'super',
  'property',
  'staticmethod',
  'classmethod',
])

export function extractContractSummary(
  acceptanceCriteria: string[],
): ContractEntry[] {
  return (acceptanceCriteria || [])
    .map((ac): ContractEntry | null => {
      const funcMatch = ac.match(/(?<!['"-])(\w+)\(([^)]*)\)/)
      const retMatch = ac.match(/returns?\s+(?:a\s+)?(\w+)/i)
      const raiseMatch = ac.match(/[Rr]aises?\s+(\w+Error|\w+Exception)/)
      if (!funcMatch || BUILTIN_SKIP.has(funcMatch[1])) return null
      return {
        function: funcMatch[1],
        args: funcMatch[2]
          ? funcMatch[2]
              .split(',')
              .map((a) => a.trim())
              .filter(Boolean)
          : [],
        returns: retMatch ? retMatch[1] : null,
        raises: raiseMatch ? raiseMatch[1] : null,
        ac: ac.slice(0, 120),
      }
    })
    .filter((entry): entry is ContractEntry => entry !== null)
}

// ---------------------------------------------------------------------------
// crossValidateBugs — cross-validates bugs across skeptic lenses
// ---------------------------------------------------------------------------

interface CrossValidatedBug {
  description: string
  evidence: string
  severity: string
  lens: string
}

export function crossValidateBugs(
  skepticResults: (SkepticResult | null)[],
  lenses: SkepticLens[],
): {
  allBugs: CrossValidatedBug[]
  brokenCount: number
  crossValidated: CrossValidatedBug[]
} {
  const allBugs: CrossValidatedBug[] = []
  let brokenCount = 0

  for (let i = 0; i < lenses.length; i++) {
    const s = skepticResults[i]
    if (!s) continue
    if (s.verdict === 'BROKEN') brokenCount++
    for (const bug of s.bugs_found || []) {
      allBugs.push({ ...bug, lens: lenses[i].key })
    }
  }

  const bugDescs = allBugs.map((b) => b.description.toLowerCase().slice(0, 60))
  const crossValidated = allBugs.filter((_bug, idx) => {
    const myDesc = bugDescs[idx]
    return bugDescs.some((d, j) => j !== idx && d === myDesc)
  })

  return { allBugs, brokenCount, crossValidated }
}

// ---------------------------------------------------------------------------
// buildPacket — builds a JSON packet for TDD agents
// ---------------------------------------------------------------------------

export function buildPacket(
  taskId: string,
  testFiles: string[],
  implFiles: string[],
  lane: Lane,
  wt: string,
  cfg: PipelineConfig,
  stage: string,
  extras: Record<string, unknown> = {},
): TaskPacket {
  return {
    schema_version: '1.0',
    task_id: taskId,
    stage: stage as TaskPacket['stage'],
    title: lane.title,
    working_directory: wt,
    test_command: cfg.testCommand,
    acceptance_criteria: lane.acceptance_criteria || [],
    red_note: lane.red_note || '',
    allowed_write_files:
      stage === 'RED'
        ? testFiles
        : stage === 'GREEN'
          ? implFiles
          : [...testFiles, ...implFiles],
    forbidden_write_files:
      stage === 'RED'
        ? implFiles
        : stage === 'GREEN'
          ? testFiles
          : [],
    commit_prefix:
      stage === 'RED'
        ? `red(${taskId})`
        : stage === 'GREEN'
          ? `green(${taskId})`
          : `refactor(${taskId})`,
    ...extras,
  }
}

// ---------------------------------------------------------------------------
// renderPrompt — replaces {{key}} placeholders with values
// ---------------------------------------------------------------------------

export function renderPrompt(
  template: string,
  vars: { [key: string]: string },
): string {
  return template.replace(
    /\{\{(\w+)\}\}/g,
    (_match, key: string) => (vars as Record<string, string>)[key] ?? `{{${key}}}`,
  )
}

