import { parseAgentJson, renderPrompt } from './shared/utils'
import routeClassifyTemplate from './prompts/route-classify.md'

export const meta = {
  name: 'datum-route',
  description: 'Smart router: classify input → pick the right pipeline composition',
  phases: [
    { title: 'Classify', detail: 'sonnet reads input + artifacts, determines route and startFrom' },
  ],
}

// ── Parse args ──

const rawArgs: string = typeof args === 'string' ? args.trim().replace(/^"|"$/g, '').trim() : ''
const input: string = rawArgs || 'No input provided — check for TICKET.md'

// ── Gather signals ──

phase('Classify')

const [artifactCheck, gitCheck] = await parallel([
  () => agent(
    'Check which pipeline artifacts exist. Run:\n' +
    'echo "TICKET: $(test -f TICKET.md && echo YES || echo NO)"\n' +
    'echo "SPEC: $(test -f SPEC.md && echo YES || echo NO)"\n' +
    'echo "TASKS: $(test -f TASKS.md && echo YES || echo NO)"\n' +
    'echo "LANE_PLAN: $(test -f .datum/lane-plan.json && echo YES || echo NO)"\n' +
    'echo "PROPERTIES: $(test -f PROPERTIES.md && echo YES || echo NO)"\n' +
    'echo "RUNS: $(ls .datum/runs/ 2>/dev/null | tail -3 || echo NONE)"\n' +
    'Return the raw output only.',
    { label: 'check-artifacts', model: 'haiku' },
  ),
  () => agent(
    'Run these commands and return the raw output:\n' +
    'git rev-parse --abbrev-ref HEAD\n' +
    'git log --oneline -5\n' +
    'git status --short | head -10',
    { label: 'check-git', model: 'haiku' },
  ),
])

// ── Classify with sonnet ──

const ROUTE_SCHEMA = {
  type: 'object' as const,
  properties: {
    route: { type: 'string' as const, enum: ['feature', 'hotfix', 'spike', 'audit', 'resume', 'refine-only'] },
    startFrom: { type: 'string' as const, enum: ['refine', 'plan', 'properties', 'act', 'validate', 'review', 'closeout'] },
    confidence: { type: 'number' as const },
    reasoning: { type: 'string' as const },
    signals: {
      type: 'object' as const,
      properties: {
        intent: { type: 'string' as const },
        scope: { type: 'string' as const, enum: ['narrow', 'moderate', 'broad'] },
        has_spec: { type: 'boolean' as const },
        has_tasks: { type: 'boolean' as const },
        has_lane_plan: { type: 'boolean' as const },
        has_properties: { type: 'boolean' as const },
        branch_type: { type: 'string' as const, enum: ['main', 'feature', 'hotfix'] },
        input_type: { type: 'string' as const, enum: ['ticket', 'bug', 'question', 'audit', 'continuation', 'raw-idea'] },
      },
      required: ['intent', 'scope', 'has_spec', 'has_tasks', 'has_lane_plan', 'has_properties', 'branch_type', 'input_type'],
    },
  },
  required: ['route', 'startFrom', 'confidence', 'reasoning', 'signals'],
}

const classifyPrompt = renderPrompt(routeClassifyTemplate, {
  input,
  artifacts: String(artifactCheck || 'could not check'),
  gitState: String(gitCheck || 'could not check'),
})

const decision = await agent(classifyPrompt, {
  label: 'classify',
  model: 'sonnet',
  schema: ROUTE_SCHEMA,
}) as {
  route: string
  startFrom: string
  confidence: number
  reasoning: string
  signals: Record<string, unknown>
}

if (!decision) throw new Error('Router classification failed — no decision returned')

log(`Route: ${decision.route} → start from: ${decision.startFrom} (${Math.round(decision.confidence * 100)}% confidence)`)
log(`Reason: ${decision.reasoning}`)

// ── Log for future model-tier analysis ──

await agent(
  'mkdir -p .datum && echo \'' +
  JSON.stringify({
    route: decision.route,
    startFrom: decision.startFrom,
    confidence: decision.confidence,
    reasoning: decision.reasoning,
    signals: decision.signals,
    input_length: input.length,
  }).replace(/'/g, "'\\''") +
  '\' >> .datum/routing.jsonl',
  { label: 'log-decision', model: 'haiku' },
)

// ── Return invocation instructions ──
// datum-route does NOT call datum-go (that would nest workflow() 2 levels)
// Instead it returns the exact args for the caller to invoke datum-go

const ROUTE_PHASES: Record<string, string[]> = {
  'feature':      ['refine', 'plan', 'properties', 'act', 'validate', 'review', 'closeout'],
  'hotfix':       ['act', 'validate', 'review'],
  'spike':        ['refine', 'plan'],
  'audit':        ['properties', 'validate', 'review'],
  'resume':       [], // determined by startFrom
  'refine-only':  ['refine'],
}

const invoke = {
  workflow: 'datum-go',
  args: {
    yolo: true,
    startFrom: decision.startFrom,
    route: decision.route,
    phases: ROUTE_PHASES[decision.route] || [],
  },
}

log(`\nNext: Workflow({ name: "${invoke.workflow}" }, ${JSON.stringify(invoke.args)})`)

export const __workflowResult = {
  route: decision.route,
  startFrom: decision.startFrom,
  confidence: decision.confidence,
  reasoning: decision.reasoning,
  signals: decision.signals,
  invoke,
}

import type { LanePlan, LaneOutcome, SetupResult, LaneResult } from './shared/types'
import { buildWaves, parseAgentJson } from './shared/utils'

export const meta = {
  name: 'datum-go',
  description: 'Full pipeline: TICKET → SPEC → Plan → Properties → Act → Validate → Review → Closeout',
  phases: [],
}

// ── Parse args ──

const rawArgs: string = typeof args === 'string' ? args.trim().replace(/^"|"$/g, '').trim() : ''
const a = (typeof args === 'string')
  ? (rawArgs.toLowerCase() === 'yolo' ? { yolo: true } : JSON.parse(args))
  : (args || {})

const yolo: boolean = !!a.yolo
const startFrom: string = (a.startFrom || 'refine').toLowerCase()
const route: string = (a.route || 'feature').toLowerCase()
const activePhases: string[] = a.phases && a.phases.length > 0
  ? a.phases
  : ['refine', 'plan', 'properties', 'act', 'validate', 'review', 'closeout']

const PHASE_ORDER = ['refine', 'plan', 'properties', 'act', 'validate', 'review', 'closeout']
const startIdx = PHASE_ORDER.indexOf(startFrom)
if (startIdx === -1) {
  throw new Error(`Unknown phase: ${startFrom}. Valid: ${PHASE_ORDER.join(', ')}`)
}

function shouldRun(phase: string, idx: number): boolean {
  return !haltedAt && startIdx <= idx && activePhases.includes(phase)
}

log(`datum go — route: ${route}, start: ${startFrom}${yolo ? ' (yolo)' : ''}`)

// ── Pipeline ──

interface PhaseResult {
  gatePassed?: boolean
  gateMessage?: string
  testsPassed?: boolean
  criticalFindings?: number
  canMerge?: boolean
  completed?: number
  failed?: number
  failedLanes?: string[]
  taskCount?: number
  [key: string]: unknown
}

let lastResult: PhaseResult = {}
let haltedAt = ''

// Refine
if (shouldRun('refine', 0)) {
  log('── Refine ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-refine.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.gatePassed) {
    haltedAt = 'refine'
    log(`Refine gate held: ${lastResult.gateMessage || 'needs review'}. Address QUESTIONS.md, then: datum go --start-from plan`)
  } else {
    log('Refine complete')
  }
}

// Plan
if (shouldRun('plan', 1)) {
  log('── Plan ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-plan.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.gatePassed) {
    haltedAt = 'plan'
    log(`Plan gate held: ${lastResult.gateMessage || 'needs approval'}. Review TASKS.md, then: datum go --start-from properties`)
  } else {
    log(`Plan complete — ${lastResult.taskCount || '?'} tasks`)
  }
}

// Properties
if (shouldRun('properties', 2)) {
  log('── Properties ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-properties.js' }, yolo ? 'yolo' : {}) as PhaseResult
  log('Properties complete')
}

// Act — inlined from datum-tdd-act to avoid workflow() nesting limit
// (datum-tdd-act calls setup/lane/merge/docs/triage as child workflows;
//  if datum-go also called datum-tdd-act as a child, that would be 2 levels deep)
if (shouldRun('act', 3)) {
  log('── Act ──')

  const lanePlanPath = '.datum/lane-plan.json'
  const testCommand = 'uv run pytest -x -q'
  const language = 'python'

  // Detect branch + generate runId
  const branchInfo = await agent(
    'Run these two commands and return ONLY a JSON object with two fields:\n' +
    '1. "branch": output of `git rev-parse --abbrev-ref HEAD`\n' +
    '2. "timestamp": output of `date +%Y%m%d-%H%M%S`\n' +
    'Output raw JSON only. No markdown fences, no explanation.',
    { label: 'act-detect', model: 'haiku' },
  )
  const info = parseAgentJson(branchInfo, { branch: '', timestamp: '' }) as { branch: string; timestamp: string }
  const epicBranch = info.branch
  const runId = info.timestamp
  if (!epicBranch || !runId) throw new Error(`Failed to detect branch/timestamp: ${JSON.stringify(info)}`)

  // Read lane plan
  const planText = await agent(
    `Read ${lanePlanPath} and return its contents as raw JSON text. Output ONLY the JSON, no markdown fences, no explanation.`,
    { label: 'read-plan', model: 'haiku' },
  )
  const lanePlan: LanePlan = typeof planText === 'string'
    ? JSON.parse(planText.replace(/```[a-z]*\n?/g, '').trim())
    : planText

  const waves = buildWaves(lanePlan)
  if (waves.length === 0 || Object.keys(lanePlan.lanes || {}).length === 0) {
    throw new Error('Lane plan has 0 tasks — nothing to execute')
  }
  log(`Topology: ${lanePlan.total_lanes} lanes in ${waves.length} waves`)

  // Batch partitioning
  const MAX_BATCH = 5
  const allLaneIds = lanePlan.topological_order
  const batches: string[][] = []
  for (let i = 0; i < allLaneIds.length; i += MAX_BATCH) {
    batches.push(allLaneIds.slice(i, i + MAX_BATCH))
  }
  if (batches.length > 1) {
    log(`Auto-partitioned ${lanePlan.total_lanes} tasks into ${batches.length} batches`)
  }

  // Batch loop — each sub-workflow is a DIRECT child of datum-go (1 level, not 2)
  const actResults: Record<string, LaneOutcome> = {}
  const actFailures: string[] = []
  const actCompleted: string[] = []

  for (let bi = 0; bi < batches.length; bi++) {
    const batchLaneIds = batches[bi]
    const batchTag = batches.length > 1 ? ` [batch ${bi + 1}/${batches.length}]` : ''
    const batchRunId = batches.length > 1 ? `${runId}-b${bi}` : runId

    if (batches.length > 1) log(`\n=== Batch ${bi + 1}/${batches.length}: [${batchLaneIds.join(', ')}] ===`)

    // Setup — direct child workflow
    const setup = await workflow(
      { scriptPath: 'skills/datum-tdd-act-setup.js' },
      { batchRunId, epicBranch, batchLaneIds, lanePlan, batchTag },
    ) as SetupResult

    // Lane execution — direct child workflow
    const act = await workflow(
      { scriptPath: 'skills/datum-tdd-act-lane.js' },
      {
        batchLaneIds, lanePlan, worktreePaths: setup.worktreePaths, batchTag,
        cfg: { lanePlanPath, epicBranch, runId: batchRunId, testCommand, language },
        priorFailures: actFailures,
      },
    ) as LaneResult

    // Collect results
    for (const [id, r] of Object.entries(act.results || {})) {
      actResults[id] = r
      if (!r || r.status !== 'completed') {
        actFailures.push(id)
        log(`  FAILED ${id}: ${r ? `${r.stage} — ${r.error}` : 'null result'}`)
      } else {
        actCompleted.push(id)
      }
    }
    log(`Act${batchTag} done: ${batchLaneIds.filter(id => actCompleted.includes(id)).length}/${batchLaneIds.length} succeeded`)

    // Merge + Cleanup — direct child workflow
    await workflow(
      { scriptPath: 'skills/datum-tdd-act-merge.js' },
      {
        epicBranch,
        completedIds: batchLaneIds.filter(id => actCompleted.includes(id)),
        batchRunId,
        topoOrder: lanePlan.topological_order,
        batchTag,
      },
    )
  }

  // Docs — direct child workflow
  await workflow(
    { scriptPath: 'skills/datum-tdd-act-docs.js' },
    { completedLanes: actCompleted, lanePlan, runId },
  )

  // Triage — direct child workflow
  if (actFailures.length > 0) {
    await workflow(
      { scriptPath: 'skills/datum-tdd-act-triage.js' },
      { failures: actFailures, results: actResults, lanePlan, runId, epicBranch },
    )
  }

  log(`Act complete — ${actCompleted.length}/${lanePlan.total_lanes} succeeded, ${actFailures.length} failed`)
  lastResult = { completed: actCompleted.length, failed: actFailures.length, failedLanes: actFailures }
}

// Validate
if (shouldRun('validate', 4)) {
  log('── Validate ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-validate.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.testsPassed) {
    haltedAt = 'validate'
    log('Validate FAILED — tests are red. Pipeline halted.')
  } else {
    log('Validate complete')
  }
}

// Review
if (shouldRun('review', 5)) {
  log('── Review ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-review.js' }, yolo ? 'yolo' : {}) as PhaseResult
  if (!yolo && !lastResult.canMerge) {
    haltedAt = 'review'
    log(`Review: ${lastResult.criticalFindings || '?'} critical issues. Fix, then: datum go --start-from validate`)
  } else {
    log('Review complete — clear to merge')
  }
}

// Closeout
if (shouldRun('closeout', 6)) {
  log('── Closeout ──')
  lastResult = await workflow({ scriptPath: 'skills/datum-closeout.js' }, yolo ? 'yolo' : {}) as PhaseResult
  log('Closeout complete')
}

if (haltedAt) {
  log(`\nPipeline halted at ${haltedAt}. Resume with: datum go --start-from <next-phase>`)
} else {
  log('\n' + '='.repeat(60))
  log('DATUM GO COMPLETE')
  log('='.repeat(60))
}

export const __workflowResult = {
  phase: haltedAt || 'complete',
  halted: !!haltedAt,
  ...lastResult,
}

