  'feature':      ['refine', 'plan', 'properties', 'act', 'validate', 'review', 'closeout'],
  'hotfix':       ['act', 'validate', 'review'],
  'spike':        ['refine', 'plan'],
  'audit':        ['properties', 'validate', 'review'],
  'resume':       [], // determined by startFrom
  'refine-only':  ['refine'],
}

// Low confidence → enable gates (yolo: false) so human can catch misroutes
const invoke = {
  workflow: 'datum-go',
  args: {
    yolo: confident,
    startFrom: decision.startFrom,
    route: decision.route,
    phases: ROUTE_PHASES[decision.route] || [],
  },
}

log(`\nNext: Workflow({ name: "${invoke.workflow}" }, ${JSON.stringify(invoke.args)})`)

